// Generates the preview-variant app icons by stamping a "PREVIEW" ribbon over
// the production artwork, mirroring the orange "DEV" ribbon on the dev icons.
// The dev icons were generated by a script that was never committed
// (scripts/generate-dev-icons.js, still referenced by the generate:icons npm
// script); this one is checked in so the preview icons stay reproducible.
//
// Usage: node scripts/generate-preview-icon.js
//   assets/icon.png          -> assets/icon-preview.png
//   assets/adaptive-icon.png -> assets/adaptive-icon-preview.png

/* global Buffer, __dirname */
// Node script: the Expo ESLint preset doesn't declare Node globals here.
const sharp = require('sharp');
const path = require('path');

const SIZE = 1024;

// Diagonal band rising to the right, like the DEV ribbon, but purple so the
// three variants (prod / dev / preview) are distinguishable at a glance.
const ribbon = Buffer.from(`
<svg width="${SIZE}" height="${SIZE}" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <linearGradient id="band" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#8B5CF6"/>
      <stop offset="100%" stop-color="#5B21B6"/>
    </linearGradient>
  </defs>
  <!-- Adaptive icons are masked to the central ~626px circle (66/108 safe
       zone), so the text must fit inside it: 7 glyphs at 88px + spacing
       stay under ~520px. -->
  <g transform="rotate(-45 512 512)">
    <rect x="-400" y="427" width="1824" height="170" fill="url(#band)"/>
    <text x="512" y="512" text-anchor="middle" dominant-baseline="central"
          font-family="DejaVu Sans, Arial, sans-serif" font-weight="bold"
          font-size="88" letter-spacing="10" fill="#FFFFFF">PREVIEW</text>
  </g>
</svg>`);

const jobs = [
  ['icon.png', 'icon-preview.png'],
  ['adaptive-icon.png', 'adaptive-icon-preview.png'],
];

(async () => {
  for (const [src, out] of jobs) {
    const srcPath = path.join(__dirname, '..', 'assets', src);
    const outPath = path.join(__dirname, '..', 'assets', out);
    await sharp(srcPath)
      .composite([{ input: ribbon }])
      .png()
      .toFile(outPath);
    console.log(`wrote ${outPath}`);
  }
})();
